const blocks = JSON.parse($input.first().json.entry_json);
const allowed = new Set(['h1', 'h2', 'h3', 'p', 'bullet', 'number']);
let text = '';
const paras = blocks.filter(b => allowed.has(b.t) && String(b.text ?? '').length).map(b => {
  const clean = String(b.text).replace(/\n+/g, ' ');
  const start = text.length; text += clean + '\n';
  return { ...b, text: clean, start, end: text.length };
});
const BASE = 1;
const R = (s, e) => ({ startIndex: BASE + s, endIndex: BASE + e });
const STYLE = { h1: 'HEADING_1', h2: 'HEADING_2', h3: 'HEADING_3' };
const requests = [{ insertText: { location: { index: BASE }, text } }];
requests.push({ updateTextStyle: { range: R(0, text.length), textStyle: {}, fields: 'bold,italic,link,foregroundColor' } });
requests.push({ deleteParagraphBullets: { range: R(0, text.length) } });
for (const p of paras) {
  requests.push({ updateParagraphStyle: { range: R(p.start, p.end), paragraphStyle: { namedStyleType: STYLE[p.t] || 'NORMAL_TEXT' }, fields: 'namedStyleType' } });
}
let i = 0;
while (i < paras.length) {
  const t = paras[i].t;
  if (t !== 'bullet' && t !== 'number') { i++; continue; }
  let k = i; while (k + 1 < paras.length && paras[k + 1].t === t) k++;
  requests.push({ createParagraphBullets: { range: R(paras[i].start, paras[k].end - 1),
    bulletPreset: t === 'number' ? 'NUMBERED_DECIMAL_ALPHA_ROMAN' : 'BULLET_DISC_CIRCLE_SQUARE' } });
  i = k + 1;
}
const GRAY = { color: { rgbColor: { red: 0.42, green: 0.45, blue: 0.5 } } };
for (const p of paras) {
  const all = R(p.start, p.end - 1);
  if (p.bold) requests.push({ updateTextStyle: { range: all, textStyle: { bold: true }, fields: 'bold' } });
  if (p.boldPrefix) requests.push({ updateTextStyle: { range: R(p.start, p.start + Math.min(p.boldPrefix, p.text.length)), textStyle: { bold: true }, fields: 'bold' } });
  if (p.italic) requests.push({ updateTextStyle: { range: all, textStyle: { italic: true }, fields: 'italic' } });
  if (p.gray) requests.push({ updateTextStyle: { range: all, textStyle: { foregroundColor: GRAY }, fields: 'foregroundColor' } });
  if (p.link && /^https:\/\//.test(p.link)) requests.push({ updateTextStyle: { range: all, textStyle: { link: { url: p.link } }, fields: 'link' } });
}
requests.push({ insertPageBreak: { location: { index: BASE + text.length } } });
return [{ json: { requests, characters: text.length, paragraphs: paras.length } }];
